namespace L0 {
  static const float L0_SCROLL_SPEED = 0.12f;  // ramp cycles per second
  static float L0_phase = 0.0f;                // wrapped 0..1
  static float L0_invW  = 1.0f;

  void setup() {
    L0_phase = 0.0f;
    L0_invW  = 1.0f / (float)FRAME_W;
  }

  void update(float dt, const InputFrame& input) {
    (void)input;
    L0_phase = PFMath::fract(L0_phase + dt * L0_SCROLL_SPEED);
  }

  void draw() {
    for (int x = 0; x < FRAME_W; x++) {
      float v = (float)x * L0_invW + L0_phase;
      if (v >= 1.0f) v -= 1.0f;
      // Contrast S-curve: less time in the washed-out middle of the ramp,
      // more in its ends (identical per column, so computed once per x)
      v = v * v * (3.0f - 2.0f * v);
      for (int y = 0; y < FRAME_H; y++) {
        L0_setValue(x, y, v);
      }
    }
  }
}
